import fs from 'node:fs'
import { chromium } from '@playwright/test'

const ROOT = '/home/zhaodan/work/NodeJsProjects/agent-hub-web'
const OUT = `${ROOT}/.tmp/pixel/shots`
fs.mkdirSync(OUT, { recursive: true })

const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const pp = await ctx.newPage()

async function protoShot(file, name, pageName, selector) {
  await pp.goto(`file://${ROOT}/docs/prototypes/${file}`)
  await pp.waitForTimeout(700)
  if (pageName) {
    await pp.evaluate(
      ([name, sel]) => {
        document.querySelectorAll(sel).forEach((el) => {
          el.hidden = el.getAttribute('data-page') !== name
        })
        document
          .querySelectorAll('.sb-nav-item[data-page], .rail-link[data-page]')
          .forEach((el) => el.classList.toggle('is-active', el.getAttribute('data-page') === name))
      },
      [pageName, selector],
    )
  }
  await pp.waitForTimeout(700)
  await pp.screenshot({ path: `${OUT}/${name}.png` })
  console.log('shot', name)
}

await protoShot('ui-v7.html', 'proto-v7-chat')

for (const p of ['agents', 'workflows', 'tasks', 'knowledge']) {
  await protoShot('ui-v7-pages.html', `proto-v7-${p}`, p, '.page[data-page]')
}
await protoShot('ui-v7-pages.html', 'proto-v7-settings', 'settings', '.page[data-page]')

for (const p of ['overview', 'users', 'roles', 'menus', 'dict', 'audit', 'system']) {
  await protoShot('ui-v8-admin.html', `proto-v8-${p}`, p, '.admin-page[data-page]')
}

await browser.close()
console.log('done')

